"""Write docs/CONFIG.md from the Settings model (every setting, its default, bounds and description)."""
import json

from django.conf import settings as dj
from django.core.management.base import BaseCommand

from llmwiki.conf import GROUP_LABELS, Settings


class Command(BaseCommand):
    help = "Regenerate docs/CONFIG.md from llmwiki/conf.py"

    def handle(self, *a, **o):
        lines = ["# Configuration reference", "",
                 "Generated by `manage.py docs_config` from `llmwiki/conf.py`. Every value can be changed in the portal "
                 "(Agent › Settings) or in `data/settings.yaml` (bootstrap). Saved portal settings win over the YAML file.", ""]
        defaults = json.loads(Settings().model_dump_json())
        for g, field in Settings.model_fields.items():
            lines += [f"## {GROUP_LABELS.get(g, g)} (`{g}`)", ""]
            doc = (field.annotation.__doc__ or "").strip()
            if doc and not doc.startswith("!!!"):
                lines += [doc, ""]
            lines += ["| Setting | Default | Range / options | Description |", "|---|---|---|---|"]
            for name, f in field.annotation.model_fields.items():
                d = defaults[g][name]
                dv = json.dumps(d, ensure_ascii=False)
                if len(dv) > 80:
                    dv = dv[:77] + "…"
                rng = ""
                for m in f.metadata:
                    if hasattr(m, "ge"):
                        rng += f"≥ {m.ge} "
                    if hasattr(m, "le"):
                        rng += f"≤ {m.le}"
                ann = str(f.annotation)
                if "Literal" in ann:
                    rng = ann.split("Literal[")[1].split("]")[0].replace("'", "")
                desc = (f.description or "").replace("|", "/")
                tier = (f.json_schema_extra or {}).get("tier") if isinstance(f.json_schema_extra, dict) else None
                lines.append(f"| `{g}.{name}` | `{dv.replace('|', '/')}` | {rng.strip()} | {('**' + tier + '** · ') if tier else ''}{desc} |")
            lines.append("")
        p = dj.BASE_DIR / "docs" / "CONFIG.md"
        p.write_text("\n".join(lines), encoding="utf-8")
        self.stdout.write(f"wrote {p}")
